+	/** Returns the squared distance from a point to the closest point of a bounding box. */
+	public static float distanceToBoundsSquared (Vector3 point, BoundingBox bounds) {
+		final float dx = point.x < bounds.min.x ? bounds.min.x - point.x
+			: (point.x > bounds.max.x ? point.x - bounds.max.x : 0f);
+		final float dy = point.y < bounds.min.y ? bounds.min.y - point.y
+			: (point.y > bounds.max.y ? point.y - bounds.max.y : 0f);
+		final float dz = point.z < bounds.min.z ? bounds.min.z - point.z
+			: (point.z > bounds.max.z ? point.z - bounds.max.z : 0f);
+		return dx * dx + dy * dy + dz * dz;
+	}
