		final int percent = fullTriangles == 0 ? 0 : visibleTriangles * 100 / fullTriangles;
		final String modeName = mode == AUTO ? "AUTO LOD" : (mode == FULL_DETAIL ? "FULL DETAIL" : "ONE COARSE CHUNK");

