					sampleY = node.sampleY;
					normal.set(0f, 0f, -1f);
					break;
				case 1:
					sampleX = maxX;
					sampleY = node.sampleY + i * step;
					normal.set(1f, 0f, 0f);
					break;
				case 2:
					sampleX = maxX - i * step;
					sampleY = maxY;
					normal.set(0f, 0f, 1f);
					break;
				default:
					sampleX = node.sampleX;
					sampleY = maxY - i * step;
					normal.set(-1f, 0f, 0f);
					break;
				}
				writeVertex(vertices, vertexSize, posOffset, normalOffset, uvOffset, colorOffset, packedColorOffset, vertex++,
					sampleX, sampleY, normal);
			}
			edgeBottom[edge] = vertex;
			for (int i = 0; i < count; i++) {
				final int sampleX;
				final int sampleY;
				switch (edge) {
				case 0:
					sampleX = node.sampleX + i * step;
					sampleY = node.sampleY;
					normal.set(0f, 0f, -1f);
					break;
				case 1:
					sampleX = maxX;
					sampleY = node.sampleY + i * step;
					normal.set(1f, 0f, 0f);
					break;
				case 2:
					sampleX = maxX - i * step;
					sampleY = maxY;
					normal.set(0f, 0f, 1f);
					break;
				default:
					sampleX = node.sampleX;
					sampleY = maxY - i * step;
					normal.set(-1f, 0f, 0f);
					break;
