				final short top1 = (short)(edgeTop[edge] + i + 1);
				final short bottom0 = (short)(edgeBottom[edge] + i);
				final short bottom1 = (short)(edgeBottom[edge] + i + 1);
				indices[index++] = top0;
				indices[index++] = top1;
				indices[index++] = bottom0;
				indices[index++] = top1;
				indices[index++] = bottom1;
				indices[index++] = bottom0;
			}
