import java.lang.reflect.Proxy;
import org.junit.Test;

public class TerrainLodTest {

	@Test
	public void testCreatesChunksAndRenderables () {
		GL20 previousGl = Gdx.gl;
		GL20 previousGl20 = Gdx.gl20;
		Gdx.gl = Gdx.gl20 = (GL20)Proxy.newProxyInstance(GL20.class.getClassLoader(), new Class<?>[] {GL20.class}, new StubGL20());

		TerrainLod terrain = null;
		try {
			final int samples = 17;
			float[] heights = new float[samples * samples];
			for (int i = 0; i < heights.length; i++)
				heights[i] = (i % 7) * 0.1f;

			TerrainLod.Config config = new TerrainLod.Config();
			config.size.set(16f, 4f, 16f);
			config.maxDepth = 2;
			config.material = new Material();
			terrain = new TerrainLod(heights, samples, samples, config);

			assertEquals(21, terrain.getChunks().size);
			assertEquals(1024, terrain.getFullDetailTriangleCount());
			assertEquals(1344, terrain.getTotalTriangleCount());

			TestCamera camera = new TestCamera(8f, 20f, 8f);
			camera.includeAll();
			terrain.setLodDistances(new float[] {Float.MAX_VALUE, Float.MAX_VALUE});
			terrain.update(camera);

			assertEquals(16, terrain.getVisibleChunkCount());
			assertEquals(1024, terrain.getVisibleTriangleCount());
			assertEquals(16, terrain.getVisibleChunkCount(2));

			Array<Renderable> renderables = new Array<>();
			Pool<Renderable> pool = new Pool<Renderable>() {
				@Override
				protected Renderable newObject () {
					return new Renderable();
				}
			};
			terrain.getRenderables(renderables, pool);
			assertEquals(16, renderables.size);
			for (int i = 0; i < renderables.size; i++) {
				Renderable renderable = renderables.get(i);
				assertNotNull(renderable.meshPart.mesh);
				assertSame(config.material, renderable.material);
				assertNotNull(renderable.userData);
			}
		} finally {
			if (terrain != null) terrain.dispose();
			Gdx.gl = previousGl;
			Gdx.gl20 = previousGl20;
		}
	}

	private static class StubGL20 implements InvocationHandler {
		@Override
		public Object invoke (Object proxy, Method method, Object[] args) {
			Class<?> returnType = method.getReturnType();
			if (returnType == int.class) return 0;
			if (returnType == boolean.class) return false;
			if (returnType == float.class) return 0f;
			if (returnType == long.class) return 0L;
			if (returnType == short.class) return (short)0;
			if (returnType == byte.class) return (byte)0;
			if (returnType == char.class) return (char)0;
			if (returnType == double.class) return 0d;
			return null;
